recipes.code:
{
  "inputs": [
    {
      "id": "mushi-api-key",
      "type": "promptString",
      "description": "Project ingest/admin API key minted in the Mushi console (Settings → API Keys). Scope mcp:read for triage, mcp:write to dispatch fixes.",
      "password": true
    }
  ],
  "servers": {
    "mushi-mushi": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@mushi-mushi/mcp@0.20.0"
      ],
      "env": {
        "MUSHI_API_KEY": "${input:mushi-api-key}",
        "MUSHI_PROJECT_ID": "<mushi-project-id>",
        "MUSHI_API_ENDPOINT": "<mushi-api-endpoint>",
        "MUSHI_FEATURES": "<mushi-features>"
      }
    }
  }
}
